def _check_cuda_tensor(tensor: torch.Tensor, name: str, dtype: torch.dtype) -> None:
    if tensor.device.type != "cuda":
        raise ValueError(f"{name} must be a CUDA tensor")
    if tensor.dtype != dtype:
        raise ValueError(f"{name} must have dtype {dtype}, got {tensor.dtype}")


def _current_stream():
    return torch.cuda.current_stream()


def _get_kernels() -> _IndexerTopKKernels:
    return _IndexerTopKKernels.get()


def _can_use_heuristic_topk(
    *,
    enable_heuristic_topk: bool,
    pre_indices: torch.Tensor | None,
    heuristic_out_values: torch.Tensor | None,
    stride1: int,
    topk: int,
    num_pre_index_rows: int,
    num_decode_rows: int,
    num_columns: int,
    bytes_per_elem: int,
    effective_split_work_threshold: int,
    force: bool = False,
) -> bool:
    if not enable_heuristic_topk and not force:
        return False
    if pre_indices is None or heuristic_out_values is None:
        return False
    if stride1 != 1:
        return False
    if topk not in (512, 1024, 2048):
        return False
    if pre_indices.shape != (num_pre_index_rows, topk):
        return False
    if force:
        return True
    k_bs_large, k_seq_small = _heuristic_topk_hardware_bounds(
        num_columns=num_columns,
        bytes_per_elem=bytes_per_elem,
    )
    return (
        num_columns >= k_seq_small
        and num_columns < effective_split_work_threshold
        and num_decode_rows < k_bs_large
    )


def _heuristic_topk_hardware_bounds(
    *, num_columns: int, bytes_per_elem: int
) -> tuple[int, int]:
    props = torch.cuda.get_device_properties(torch.cuda.current_device())
    sm_count = props.multi_processor_count
    l2_bytes = getattr(props, "l2_cache_size", 0)
    seq_small = HEURISTIC_SEQUENCE_LENGTH_THRESHOLD
    env_seq_small = os.getenv("TRTLLM_HEURISTIC_NMIN")
    if env_seq_small is not None:
        try:
            value = int(env_seq_small)
        except ValueError:
            value = seq_small
        if 1024 <= value <= 200000:
            seq_small = value
    bs_wave = sm_count * 3 - sm_count // 8 if sm_count > 0 else 426
    if l2_bytes > 0 and num_columns > 0:
        bs_l2 = int(l2_bytes * 9 // 10 // (num_columns * bytes_per_elem))
    else:
        bs_l2 = bs_wave
    bs_large = min(bs_wave, bs_l2 if bs_l2 > 0 else bs_wave)
    return bs_large, seq_small


def _effective_split_work_threshold(
    *, split_work_threshold: int, phase: str
) -> int:
    if split_work_threshold > 0:
        return split_work_threshold
    if phase == "prefill":
        return 1 << 30
    return SPLIT_WORK_THRESHOLD


def _select_indexer_topk_impl(
    *,
    phase: str,
    num_rows: int,
    num_columns: int,
    topk: int,
    stride1: int,
    split_work_threshold: int = SPLIT_WORK_THRESHOLD,
    sorting_algorithm_threshold: int = SORTING_ALGORITHM_THRESHOLD,
    requested_impl: str = "auto",
    enable_heuristic_topk: bool = False,
    pre_indices: torch.Tensor | None = None,
    heuristic_out_values: torch.Tensor | None = None,
    next_n: int = 1,
    bytes_per_elem: int = 4,
    has_split_aux: bool = False,
) -> str:
    if phase not in INDEXER_TOPK_PHASES:
        raise ValueError(
            f"phase must be one of {sorted(INDEXER_TOPK_PHASES)}, got {phase!r}"
        )
    if phase == "prefill":
        if requested_impl not in INDEXER_TOPK_PREFILL_IMPLS:
            raise ValueError(
                f"requested_impl must be one of {sorted(INDEXER_TOPK_PREFILL_IMPLS)}, got {requested_impl!r}"
            )
        return "radix"
    if requested_impl not in INDEXER_TOPK_DECODE_IMPLS:
        raise ValueError(
            f"requested_impl must be one of {sorted(INDEXER_TOPK_DECODE_IMPLS)}, got {requested_impl!r}"
        )

    if requested_impl != "auto":
        return requested_impl

    effective_split_work_threshold = _effective_split_work_threshold(
        split_work_threshold=split_work_threshold,
        phase=phase,
    )
    if num_columns <= topk:
        return "dense"
    if num_columns < sorting_algorithm_threshold:
        return "radix"
    if _can_use_heuristic_topk(
        enable_heuristic_topk=enable_heuristic_topk,
        pre_indices=pre_indices,
        heuristic_out_values=heuristic_out_values,
        stride1=stride1,
        topk=topk,
        num_pre_index_rows=num_rows // next_n,
        num_decode_rows=num_rows,
        num_columns=num_columns,
        bytes_per_elem=bytes_per_elem,
        effective_split_work_threshold=effective_split_work_threshold,
    ):
        return "heuristic"
    if num_columns < effective_split_work_threshold:
        return "radix"
    if stride1 == 1 and not has_split_aux:
        return "multi_radix"
    return "split"


def invoke_indexer_topk_prefill(
    logits: torch.Tensor,
    row_starts: torch.Tensor,
    row_ends: torch.Tensor,
    topk: int,
    stride0: int | None = None,
    stride1: int = 1,
    out_indices: torch.Tensor | None = None,
    sorting_algorithm_threshold: int = SORTING_ALGORITHM_THRESHOLD,
) -> torch.Tensor:
    _check_cuda_tensor(logits, "logits", torch.float32)
    _check_cuda_tensor(row_starts, "row_starts", torch.int32)
    _check_cuda_tensor(row_ends, "row_ends", torch.int32)
    if row_starts.numel() != row_ends.numel():
        raise ValueError(
            "row_starts and row_ends must have the same number of elements"
        )

    if stride0 is None:
        stride0 = logits.shape[-1]
    num_rows = row_starts.numel()
    if out_indices is None:
        out_indices = torch.empty(
            (num_rows, topk), device=logits.device, dtype=torch.int32
        )
    else:
        _check_cuda_tensor(out_indices, "out_indices", torch.int32)
        expected_shape = (num_rows, topk)
        if tuple(out_indices.shape) != expected_shape:
            raise ValueError(
                f"out_indices must have shape {expected_shape}, got {tuple(out_indices.shape)}"
            )
    kernels = _get_kernels()
    stream = _current_stream()
    shared_mem = topk * INT32_BYTES
    selected_impl = _select_indexer_topk_impl(
        phase="prefill",
        num_rows=num_rows,
        num_columns=logits.shape[1],
        topk=topk,
        stride1=stride1,
        sorting_algorithm_threshold=sorting_algorithm_threshold,
    )
    assert selected_impl == "radix"
    kernels.prefill_radix(
        grid=(num_rows, 1, 1),
        block=(NUM_THREADS_PER_BLOCK, 1, 1),
        args=[
            logits,
            row_starts,
            row_ends,
            out_indices,
            stride0,
            stride1,
            topk,
            0,
        ],
        shared_mem=shared_mem,
        stream=stream,
    )

    return out_indices
